import ast
import subprocess
from pathlib import Path

def docstrings(source):
    return {getattr(node, 'name', '<module>'): ast.get_docstring(node, clean=False)
            for node in ast.walk(ast.parse(source))
            if isinstance(node, (ast.Module, ast.FunctionDef, ast.ClassDef))
            and ast.get_docstring(node, clean=False) is not None}

for path in Path('tally').glob('*.py'):
    old = subprocess.check_output(['git', 'show', f'HEAD:{path}'], text=True)
    assert docstrings(old) == docstrings(path.read_text()), path
